usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Chat.Completions.List(
		context.TODO(),
		openai.ChatCompletionListParams{
			Model: param.NewOpt[string]("model"),
			Metadata: map[string]string{"key": "string"},
			After: param.NewOpt[string]("after"),
			Limit: param.NewOpt[int64](20),
			Order: param.NewOpt[openai.ChatCompletionsListOrder](openai.ChatCompletionsListOrderAsc),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
